SELECT CASE WHEN credit_limit >= 15500 THEN 'PREMIUM' ELSE 'STANDARD' END AS credit_limit_tier, city, PERCENTILE_APPROX(credit_limit, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_quartiles, COUNT(*) AS cnt, ROUND(AVG(age), 2) AS avg_age, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) AS row_count FROM customers GROUP BY CASE WHEN credit_limit >= 15500 THEN 'PREMIUM' ELSE 'STANDARD' END, city
